import sys
from typing import List

def read_input() -> List[str]:
    return [line.strip() for line in sys.stdin.readlines()]

def find_relation(melody1: List[str], melody2: List[str]) -> str:
    def transpose(melody: List[str], n: int) -> List[str]:
        return [(chr((ord(note) - ord('C') + n) % 12 + ord('C')) for note in melody]

    def retrograde(melody: List[str]) -> List[str]:
        return melody[::-1]

    def inversion(melody: List[str]) -> List[str]:
        return [melody[0]] + [(chr(2 * ord('C') - ord(melody[0]) - ord(note)) for note in melody[1:])]

    for n in range(12):
        if melody2 == transpose(melody1, n):
            return "Transposition"

    if melody2 == retrograde(melody1):
        return "Retrograde"

    if melody2 == inversion(melody1):
        return "Inversion"

    return "Nonsense"

