def find_relation(melody1, melody2):
    n = len(melody1)

    # Define note positions
    notes = "C C# D D# E F F# G G# A A# B"
    note_positions = {note: i for i, note in enumerate(notes.split())}

    def transposed(melody):
        return [melody[i - 1] for i in range(1, n + 1)]

    def retrograded(melody):
        return melody[::-1]

    def inverted(melody):
        return [melody[0]] + [notes[(note_positions[melody[i]] - note_positions[melody[0]]) % 12] for i in range(1, n)]

    if melody2 == transposed(melody1):
        return "Transposition"
    elif melody2 == retrograded(melody1):
        return "Retrograde"
    elif melody2 == inverted(melody1):
        return "Inversion"
    else:
        return "Nonsense"

